# =============================================================================
# Blocked compact-WY kernels (orgqr_wy_kernel lineage, 2026-11-16 orgqr case).
# Groups BLOCK_K consecutive reflectors into one rank-BLOCK_K update
# P = I - V T V^T so the serial chain shrinks from K steps to K/BLOCK_K.
#
# Correctness notes (all measured on this backend, see knowledge/):
# - 1-D loads with descending index vectors return scrambled values, so the
#   reflector block is loaded with ASCENDING k and the mirrored WY form is
#   used: the nilpotent generator L~[i,m] = tau_i * S[i,m] is strictly UPPER.
# - 2-D masked loads whose row mask (negative reflector index) is partially
#   false return garbage instead of ``other``; addresses are clamped into
#   range and padded reflector rows are zeroed with an explicit where.
# - Out-of-range reflectors (negative for REVERSE partial blocks, >= K for
#   FORWARD partial blocks) become zero columns: v = 0 and tau = 0, an
#   identity no-op that keeps S/T well-formed.
# - T = (I + L~)^-1 diag(tau) via the nilpotent factorization
#   (I-L~)(I+L~^2)(I+L~^4)(I+L~^8)...: LOG2_STEPS = ceil(log2(BLOCK_K)) - 1.
# - (REVERSE, TT) mapping from the aten flags:
#     left:  REVERSE = not transpose, TT = transpose
#     right: REVERSE = transpose,     TT = transpose
#   REVERSE selects the block sweep order (highest reflectors first), TT
#   selects Tm vs Tm^T in the middle product. CPU-validated against
#   brute-force sequential application for all four flag combinations
#   (real geqrf reflectors, worst rel err 1.3e-12).
# =============================================================================


@libentry()
@triton.jit
def _ormqr_wy_left_kernel(
    C_ptr,
    input_ptr,
    tau_ptr,
    M,
    N,
    K,
    stride_cb,
    stride_cm,
    stride_cn,
    stride_ib,
    stride_im,
    stride_ik,
    stride_tb,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    LOG2_STEPS: tl.constexpr,
    REVERSE: tl.constexpr,
    TT: tl.constexpr,
):
    """Resident-tile compact-WY, left application. Grid: (col_tiles, batch).

    Each program owns one BLOCK_N-wide column tile of C, keeps it on-chip
    across all reflector blocks, and stores it once. For M <= 256.
    """
    col_tile = tl.program_id(0)
    bid = tl.program_id(1)

    cols = col_tile * BLOCK_N + tl.arange(0, BLOCK_N)
    rows = tl.arange(0, BLOCK_M)
    kk = tl.arange(0, BLOCK_K)
    row_mask = rows < M
    col_mask = cols < N

    c_base = C_ptr + bid * stride_cb
    i_base = input_ptr + bid * stride_ib
    t_base = tau_ptr + bid * stride_tb

    c_tile = tl.load(
        c_base + rows[:, None] * stride_cm + cols[None, :] * stride_cn,
        mask=row_mask[:, None] & col_mask[None, :],
        other=0.0,
    )
    # Transposed state tile ([BLOCK_N, BLOCK_M], M axis trailing) exactly
    # like orgqr_wy_kernel so every per-block dot keeps the orgqr-proven
    # operand shapes ([BN, BM] x [BM, BK], [BN, BK] x [BK, BK],
    # [BN, BK] x [BK, BM]); M=16-shaped dots measured 3.7x slower per block.
    c_t = tl.trans(c_tile)
    eye = tl.where(kk[:, None] == kk[None, :], 1.0, 0.0).to(c_tile.dtype)

    for b in range(0, tl.cdiv(K, BLOCK_K)):
        if REVERSE:
            bot = K - (b + 1) * BLOCK_K
        else:
            bot = b * BLOCK_K
        kidx = bot + kk
        kmask = (kidx >= 0) & (kidx < K)
        kidx_safe = tl.minimum(tl.maximum(kidx, 0), K - 1)

        # Coalesced row-major reflector tile [BLOCK_M, BLOCK_K] (lanes run
        # along the contiguous k axis); a [BLOCK_K, BLOCK_M]-oriented load
        # strides by input_row_stride per lane and degrades to one access
        # per element (~ns/element, see the orgqr case notes).
